        body {
            margin: 0;
        }
        body.page .wrapper{
            background-color: initial !important;
        }
        .b2b_page_root section{
            text-align: left;
        }
        .gfg-icon::after {
            font-feature-settings: 'liga';
        }
        main.b2b_page_root {
            max-width: 100%;
        }
        .b2b_contact_modal_mail_text:hover{
            color: var(--primary-grren-600, #357960);
        }
        .b2b_fixed_topbar {
            height: 61px;
            display: flex;
            justify-content: flex-end;
            align-items: center;
            background: #265645;
            box-shadow: 0px 12px 24px 0px rgba(20, 20, 43, 0.04), 0px -2px 4px 0px rgba(20, 20, 43, 0.02);
            z-index: 2;
            position: sticky;
            top:40px;
            display: none;
        }
        .download-icon{
            margin-left: 5px;
            display: flex;
            width: 24px;
            height: 25px;
            background-image: url('https://media.geeksforgeeks.org/auth-dashboard-uploads/B2BIcons.svg');
            background-position: 55px -79px;
        }
        .b2b_fixed_topbar .download-icon img{
            width: 18px;
            height: 18px;
        }
        .b2b_fixed_topbar .download-icon{
            margin-left: 0px;
        }
        .b2b_fixed_topbar > button {
            display: flex;
            justify-content: center;
            align-items: center;
            font-family: var(--font-primary);
            font-size: 18px;
            font-style: normal;
            font-weight: 400;
            line-height: 18px; 
            color: #FFF;
            outline: none;
            border: none;
            cursor: pointer;
            background: none;
        }
        .b2b_fixed_topbar .b2b_connect_now {
            border-radius: 6px;
            background: #41886C;
            font-feature-settings: 'clig' off, 'liga' off;
            padding: 10px 28px;
            margin-right: 27px;
            margin-bottom: 0px;
        }
        .b2b_fixed_topbar .b2b_download_btn {
            height: 29px;
            border-radius: 11px;
            margin-right: 79px;
        }
        .b2b_fixed_topbar .b2b_download_btn span {
            margin-right: 11.5px;
        }

        .b2b_top_section {
            display: flex;
            padding: 6.5% 4.5% 6.5% 9%;
            justify-content: space-between;
        }
        .b2b_top_section .b2b_text_container {
            width: 58%;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }
        .b2b_top_section .b2b_image_container {
            max-width: 498px;
            width: 37%;
        }
        .b2b_top_section .b2b_image_container video {
            width: 100%;
            height: 100%;
            border-radius: 17px;
        }
        .b2b_top_section .b2b_heading {
            color: var(--light-mode-light-h-1, #0E0E12);
            font-family: var(--font-primary);
            font-size: 46px;
            font-style: normal;
            font-weight: 600;
            line-height: 62px; 
            margin-bottom: 8px;
        }
        .b2b_top_section .b2b_subheading {
            color: rgba(0, 0, 0, 0.50);
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 500;
            line-height: 160%; /* 25.6px */
            letter-spacing: 0.32px;
            margin-bottom: 36px;
            max-width: 593px;
        }
        .b2b_button_container {
            display: flex;
        }
        .b2b_button_container > button {
            display: flex;
            justify-content: center;
            align-items: center;            
            height: 51px;
            border-radius: 9px;
            font-family: var(--font-primary);
            font-size: 22px;
            font-style: normal;
            font-weight: 400;
            line-height: 160%; /* 35.2px */
            letter-spacing: 0.44px;
            cursor: pointer;
            outline: none;
            border: none;
        }
        .b2b_button_container .b2b_download_btn {
            width: 282px;
            background: var(--primary-grren-500, #41886C);
            color: #FFF;
            margin-right: 22px;
        }
        .b2b_button_container .b2b_apply_btn {
            width: 161px;
            border: 1px solid var(--light-mode-light-m-1, #6E6E73);
            color: #6E6E73;
            background: none;
        }
        .b2b_apply_btn a {
            color: currentColor;
            text-decoration: none;
        }

        .b2b_second_section {
            background: var(--primary-grren-100, #DDEEE4);
            padding: 56px 140px 56px 117px;
            display: flex;
        }
        .b2b_second_section>div {
            width: 50%;
        } 
        .b2b_second_section>div:first-child {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
        }
        .b2b_second_section>div:last-child {
            display: flex;
            justify-content: space-around;
            align-items: center;
            gap: 10px;
        }
        .b2b_second_section>div:last-child>div {
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        .b2b_second_section_left_title {
            color: #000 !important;
            font-family: var(--font-primary);
            font-size: 30px;
            font-style: normal;
            font-weight: 600;
            line-height: 62px; /* 206.667% */
        } 
        .b2b_second_section_left_description {
            width: 80%;
            margin-top: 12px;
            color: rgba(0, 0, 0, 0.50) !important;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 500;
            line-height: 160%; /* 28.8px */
            letter-spacing: 0.36px;
        }
        .b2b_second_section_image_container {
            width: 50px;
            height: 50px;
            display: flex;
            justify-content: center;
            align-items: center;
            border-radius: 50%;
            background-color: #62A588;
        }
        .b2b_second_section_image_container img {
            width: 24px;
        }
        .b2b_interview_img img {
            width: 22.8px;
        }
        .b2b_second_section>div:last-child>div span {
            color: #000;
            font-family: var(--font-primary);
            font-size: 22px;
            font-style: normal;
            font-weight: 600;
            margin-top: 26px;
            text-align: center;
        }

        .b2b_third_section {
            display: flex;
            flex-direction: column;
            background: #F9FBFC;
            padding: 100px 77px 63px 126px;
        }
        .b2b_third_header {
            display: flex;
            flex-direction: column;
        }
        .b2b_third_header>h2 {
            color: #000 !important;
            font-family: var(--font-primary);
            font-size: 34px;
            font-style: normal;
            font-weight: 600;
            margin-bottom: 22px;
        }
        .b2b_third_header>div {
            color: rgba(0, 0, 0, 0.50) !important;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 500;
            line-height: 160%; /* 28.8px */
            letter-spacing: 0.36px;
            max-width: 658px;
            width: 100%;
        }
        .b2b_third_body {
            display: flex;
            margin-top: 55px;
            flex-wrap: wrap;
            gap: 38px;
        }
        .b2b_third_card_container {
            background: #FFF;
            filter: drop-shadow(0px 0px 8px rgba(0, 0, 51, 0.08));
            padding: 44px 34px;
            width: 30%;
            min-width: 225px;
            border-radius: 10px;
            box-sizing: border-box;
            margin-bottom: 37px;
        }
        .b2b_third_image_container {
            height: 37px;
            margin-bottom: 40px;
        }
        .b2b_third_image_container img {
            height: 100%;
        }
        .b2b_third_card_heading {
            color: #101041;
            font-family: var(--font-primary);
            font-size: 20px;
            font-style: normal;
            font-weight: 700;
            line-height: normal;
            margin-bottom: 14px;
        }
        .b2b_third_card_subheading {
            color: rgba(0, 0, 51, 0.95);
            font-family: var(--font-secondary);
            font-size: 16px;
            font-style: normal;
            font-weight: 400;
            line-height: 26px; /* 162.5% */
        }

        .b2b_forth_section {
            padding: 70px 96px 89px;
            display: flex;
            flex-direction: column;
        }
        .b2b_forth_section_header {
            margin-bottom: 63px;
        }
        .b2b_forth_heading {
            color: #000 !important;
            font-family: var(--font-primary);
            font-size: 34px;
            font-style: normal;
            font-weight: 600;
            margin-bottom: 26px;
        }
        .b2b_forth_subheading {
            color: rgba(0, 0, 0, 0.50) !important;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 500;
            line-height: 160%;
            letter-spacing: 0.36px;
            max-width: 736px;
        }
        .b2b_forth_btn_container {
            display: flex;
            justify-content: center;
            align-items: center;
            margin-top: 41px;
        }
        .b2b_forth_btn_container button {
            border-radius: 9px;
            background: var(--primary-grren-500, #41886C);
            color: #FFF;
            font-family: var(--font-primary);
            font-size: 22px;
            font-style: normal;
            font-weight: 400;
            line-height: 160%;
            letter-spacing: 0.44px;
            border: none;
            outline: none;
            padding: 8px 29px;
        }
        .b2b_forth_btn_container button a {
            color: currentColor;
            text-decoration: none;
        }
        .b2b_forth_cards_collection {
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
        }
        .b2b_forth_card_container {
            min-width: 250px;
            width: 23%;
            margin-top: 20px;
        }
        .b2b_forth_image_container {
            width: 51px;
            height: 51px;
            border-radius: 5px;
            background: #D8D8FC;
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
            margin: auto;
        }
        .b2b_forth_image_container img {
            width: 26px;
        }
        .b2b_forth_card_text_container {
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        .b2b_forth_card_text_container>div:first-child {
            color: #000;
            font-family: var(--font-primary);
            font-size: 22px;
            font-style: normal;
            font-weight: 600;
            line-height: 160%; /* 35.2px */
            letter-spacing: 0.44px;
            margin-bottom: 12px;
        }
        .b2b_forth_card_text_container>div:last-child {
            color: rgba(0, 0, 0, 0.50);
            text-align: center;
            font-family: var(--font-secondary);
            font-size: 16px;
            font-style: normal;
            font-weight: 400;
            line-height: 160%; /* 25.6px */
            letter-spacing: 0.32px;
        }
        .b2b_forth_section_line {
            max-width: 186px;
            width: 75%;
            border-top: 1px solid #B4B4B4;
            margin: 23px auto 9px;
        }

        .b2b_faq_section {
            padding: 100px 20px 135px 20px;
            display: flex;
            flex-direction: column;
            width: 100%;
            margin: auto;
            max-width: 820px;
        }
        .b2b_faq_header {
            display: flex;
            flex-direction: column;
            align-items: center;
            margin-bottom: 50px;
        }
        .b2b_faq_heading {
            color: #000;
            font-family: var(--font-primary);
            font-size: 40px;
            font-style: normal;
            font-weight: 600;
            line-height: 140%;
            margin-bottom: 12px;
        }
        .b2b_faq_subheading {
            width: 90%;
            text-align: center;
            color: var(--neutral-700, #514F6E);
            text-align: center;
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 400;
            line-height: 30px;
        }
        .b2b_faq_accordion_container {
            border-bottom: 1px solid #D5D5D6;
            margin-bottom: 45px;
            cursor: pointer;
        }
        .b2b_faq_accordion_label { 
            display: flex;
            justify-content: space-between;
            font-family: var(--font-secondary);
            font-size: 20px;
            font-style: normal;
            font-weight: 600;
            line-height: 30px;
            color: #003;
        }
        .b2b_faq_expanded_text {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-in-out;
            color: var(--neutral-700, #514F6E);
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 400;
            line-height: 30px;
            margin-top: 20px;
        }
        .b2b_expand_accordion .b2b_faq_expanded_text {
            max-height: 100vh;
        }
        .b2b_expand_accordion .b2b_faq_accordion_label {
            margin-bottom: 8px;
        }
        i.gfg-down-icon::after {
            transform: rotate(0deg);
            background-position: -120 0px;
            transition: all 0.4s ease-in-out;
        }
        .b2b_expand_accordion  {
            border-bottom-color: transparent;
        }
        .b2b_expand_accordion i::after {
            transform: rotate(180deg);
        }
        .b2b_faq_accordion_container:last-child {
            border-bottom: none;
        }

        .testimonial_section {
            padding: 150px 100px 100px 117px;
            background: #F9FBFC;
        }
        .testimonial_section_title {
            color: var(--primary-grren-600, #357960);
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-secondary);
            font-size: 22px;
            font-style: normal;
            font-weight: 700;
            line-height: 20px;
            letter-spacing: 2.2px;
            text-transform: uppercase;
            display: flex;
            align-items: center;
            margin-bottom: 36px;
        }
        .testimonial_section_title>span:first-child {
            width: 22px;
            display: inline-block;
            height: 2px;
            background: #357960;
            margin-right: 10px;
        }
        .testimonial_section_heading {
            color: var(--neutral-800, #170F49) !important;
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-primary);
            font-size: 34px;
            font-style: normal;
            font-weight: 600;
            line-height: 46px; /* 135.294% */
            margin-bottom: 26px;
        }
        .testimonial_section_subheading {
            color: var(--neutral-700, #514F6E);
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 400;
            line-height: 30px; /* 166.667% */
            max-width: 644px;
            margin-bottom: 21px;
        }
        .testimonial_card_collection, .b2b_case_collection {
            display: flex;
            overflow-x: hidden;
            flex-wrap: nowrap;
            width: 100%;
            scroll-behavior: smooth;
        }
        .single_card {
            border-radius: 20px;
            border: 1px solid var(--neutral-300, #EFF0F6);
            background: var(--neutral-100, #FFF);
            box-shadow: 0px 5px 14px 0px rgba(8, 15, 52, 0.04);
            padding: 25px;
            margin-right: 5%;
            min-width: 30%;
            box-sizing: border-box;
        }
        @media screen and (max-width: 835px) {
            .single_card {
                min-width: 45%;
            }
        }
        @media screen and (max-width: 565px) {
            .single_card {
                min-width: 90%;
                margin-left: 5%;
            }
        }
        .single_card:last-child {
            margin-right: 0;
        }
        .single_testimonial_header {
            display: flex;
            align-items: center;
        }
        .testimonial_image_container {
            width: 38px;
            margin-right: 14px;
            height: 38px;
            display: flex;
            justify-content: center;
            align-items: center;
        }
        .testimonial_image_container img {
            width: 100%;
        }
        .testimonial_name_designation_container {
            color: var(--neutral-800, #170F49);
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-primary);
            font-size: 16px;
            font-style: normal;
            font-weight: 600;
            line-height: 20px;
        }
        .single_testimonial_words {
            margin-top: 22px;
            color: var(--neutral-700, #514F6E);
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-secondary);
            font-size: 16px;
            font-style: normal;
            font-weight: 400;
            line-height: 30px;
        }
        .placement-company {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 16px;
            color: var(--light-mode-light-m-1, #6E6E73);
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 400;
            line-height: 30px; /* 166.667% */
        }
        .placement-company img {
            height: 37px;
        }
        .testimonial_card_transition_buttons,.b2b_case_transition_buttons,.faculty_card_transition_buttons {
            display: flex;
            justify-content: center;
            width: 100%;
        }
        .testimonial_card_transition_buttons .single_dot, .b2b_case_transition_buttons .single_dot, .faculty_card_transition_buttons .single_dot {
            width: 13px;
            height: 13px;
            background: #d9d9d9;
            border-radius: 50%;
            margin: 32px 7px 0;
        }
        .testimonial_card_transition_buttons span.active_testimonial_button, .b2b_case_transition_buttons span.active_case_study_button, .faculty_card_transition_buttons span.active_faculty_button{
            background: #367e6e;
        }
        @media screen and (max-width: 565px) {
            .testimonial_card_transition_buttons .single_dot, .b2b_case_transition_buttons .single_dot, .faculty_card_transition_buttons .single_dot {
                height: 11px;
                width: 11px;
            }
        }

        .b2b_journey_section {
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: 70px 100px;
            background: #F9FBFC;
        }
        .b2b_journey_header {
            display: flex;
            flex-direction: column;
            align-items: center;
            margin-bottom: 90px;
        }
        .b2b_journey_heading {
            color: #1B1D21 !important;
            text-align: center;
            font-family: var(--font-primary);
            font-size: 34px;
            font-style: normal;
            font-weight: 600;
            line-height: normal;
            margin-bottom: 26px;
            text-transform: capitalize;
        }
        .b2b_journey_subheading {
            color: var(--neutral-700, #514F6E) !important;
            text-align: center;
            font-feature-settings: 'clig' off, 'liga' off;
            font-family: var(--font-secondary);
            font-size: 18px;
            font-style: normal;
            font-weight: 400;
            line-height: 30px;
            max-width: 658px;
        }
        .b2b_journey_info {
            display: flex;
            justify-content: center;
        }
        .b2b_journey_info>div {
            color: #357960;
            text-align: center;
            font-family: var(--font-secondary);
            font-size: 20px;
            font-style: normal;
            font-weight: 700;
            display: flex;
            align-items: center;
            margin-right: 80px;
        }
        .b2b_journey_info>div:last-child {
            margin-right: 0;
        }
        .b2b_journey_info img {
            margin-right: 10px;
            width: 20px;
        }
        .b2b_journey_body {
            margin-top: 120px;
            display: flex;
        }
        .b2b_jorney_start, .b2b_crack_interview {
            width: 115px;
            color: #757575;
            text-align: center;
            font-family: var(--font-primary);
            font-size: 24px;
            font-style: normal;
            font-weight: 700;
            line-height: normal;
            text-transform: capitalize;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }
        .b2b_jorney_start img {
            width: 80px;
        }
        .b2b_crack_interview img{
            width: 70px;
        }
        .b2b_journey_steps {
            width: calc(100% - 230px);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
        }
        .b2b_jouney_line {
            width: 100%;
            border-radius: 22px;
            background: #E9E9E9;
            height: 44px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 60px auto;
        }   
        .b2b_jouney_line img {
            width: 95%;
        }
        .b2b_jouney_part_1, .b2b_jouney_part_2 {
            display: flex;
        }
        .b2b_jouney_part_1 {
            justify-content: space-between;
            width: 95%;
        }
        .b2b_jouney_part_2 {
            justify-content: space-around;
            width: 85%;
        }
        .b2b_journey_step_circle {
            position: absolute;
            width: 7px;
            height: 7px;
            border-radius: 50%;
            border: 4px solid #41886C;
            left: auto;
            right: auto;
            background: #F9FBFC;
        }
        .b2b_jouney_part_1 .b2b_journey_step_circle {
            bottom: -86px;
        }
        .b2b_jouney_part_2 .b2b_journey_step_circle {
            top: -86px;
        }
        .b2b_journey_single_step {
            width: 135px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            align-items: center;
            position: relative;
        }
        .b2b_jouney_part_2 .b2b_journey_single_step {
            width: 155px;
        }
        .b2b_journey_single_step_info{ 
            display: flex;
            padding-right: 20px;
        }
        .b2b_journey_single_step_info>span {
            height: 30px;
            position: relative;
            top: 81px;
            color: #546C62;
            text-align: center;
            font-family: var(--font-primary);
            font-size: 24px;
